class TestBookingLinkSubmissionView(BloomerpDetailViewTestCase):
    """Exercise public scheduling and its calendar write through the detail route."""

    view_name = "booking_link_submission"
    model = BookingLink
    auto_create_customers = False

    def setUp(self) -> None:
        """Create a future schedule with separate organizing and destination calendars."""
        super().setUp()
        zone = ZoneInfo("Europe/Brussels")
        self.day = timezone.now().astimezone(zone).date() + timedelta(days=9)
        self.start = datetime.combine(self.day, time(9), zone).astimezone(UTC)
        self.end = self.start + timedelta(minutes=30)
        self.inbox = Inbox.objects.create(
            user=self.admin_user, name="Organizing calendar"
        )
        self.destination = Inbox.objects.create(
            user=self.admin_user, name="Destination calendar"
        )
        self.booking = BookingLink.objects.create(
            title="Project consultation",
            location="Room 4, ground floor",
            description=(
                "<p>Discuss <strong>your project</strong>.</p>"
                "<script>unsafeBookingDescription()</script>"
                '<a href="javascript:unsafeBookingLink()">More information</a>'
            ),
            organizing_inbox=self.inbox,
            meeting_duration_minutes=30,
            timezone=zone.key,
            availability_hours={
                "start_date": self.day.isoformat(),
                "exceptions": [
                    {
                        "date": self.day.isoformat(),
                        "hours": [{"start": "09:00", "end": "10:30"}],
                    }
                ],
            },
            active=True,
        )
        self.booking.target_inboxes.add(self.destination)

    def get_view_kwargs(self) -> dict[str, UUID]:
        """Reverse the public detail route with the booking link ID."""
        return {"pk": self.booking.pk}

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover public access, availability, approval modes, and rejected slots."""
        data = {
            "day": self.day.isoformat(),
            "slot": self.start.isoformat(),
            "name": "Guest name",
            "email": "guest@example.com",
        }
        return [
            RequestScenario(
                name="Anonymous visitors can see the offering and its available slots",
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Project consultation"),
                        self.contains_text(self.start.isoformat()),
                        self.contains_text("Europe/Brussels"),
                        self.contains_text("btn btn-primary"),
                        self.contains_text('class="input w-full"'),
                        self.contains_text("<strong>your project</strong>"),
                        self.does_not_contain_text("unsafeBookingDescription"),
                        self.does_not_contain_text("javascript:unsafeBookingLink"),
                        self.does_not_contain_text(self.inbox.name),
                    ]
                ),
            ),
            RequestScenario(
                name="An unknown booking UUID returns not found",
                user=self.normal_user,
                view_kwargs={"pk": uuid4()},
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="A disabled link rejects a previously opened booking form",
                method="POST",
                data=data,
                prepare=self.disable_link,
                expected=ExpectedResult(
                    status_code=404, response_validators=self.no_submission
                ),
            ),
            RequestScenario(
                name="A legacy schedule with unusable hours displays no times",
                prepare=self.set_legacy_hours,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("No appointments are available this month."),
                        self.does_not_contain_text('name="slot"'),
                    ]
                ),
            ),
            RequestScenario(
                name="An all-day event closes its date without exposing event details",
                prepare=self.block_day,
                expected=ExpectedResult(
                    response_validators=[
                        self.does_not_contain_text("Private event"),
                        self.does_not_contain_text('name="slot"'),
                    ]
                ),
            ),
            RequestScenario(
                name="An overlapping destination event rejects a stale slot",
                method="POST",
                data=data,
                prepare=self.block_slot,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("This time is no longer available."),
                        self.does_not_contain_text("Private event"),
                        self.no_submission,
                    ]
                ),
            ),
            RequestScenario(
                name="A cancelled event frees its slot for immediate booking by default",
                method="POST",
                data=data,
                prepare=self.add_cancelled_event,
                follow=True,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Booking confirmed"),
                        self.contains_text(self.booking.location),
                        self.approved_event,
                    ]
                ),
            ),
            RequestScenario(
                name="Without auto-approval the selected interval is saved as pending",
                method="POST",
                data=data,
                prepare=self.use_manual_approval,
                follow=True,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Your request is awaiting approval."),
                        self.pending_submission,
                    ]
                ),
            ),
            RequestScenario(
                name="Auto-approved bookings receive distinct conference links",
                method="POST",
                data=data,
                prepare=self.use_generated_meetings,
                follow=True,
                expected=ExpectedResult(response_validators=self.distinct_meeting_locations),
            ),
            RequestScenario(
                name="An auto-approved booking renders the rich confirmation in both email formats",
                prepare=self.prepare_rich_confirmation_email,
                expected=ExpectedResult(response_validators=self.auto_confirmation_email),
            ),
            RequestScenario(
                name="A booked event can use its original sender for a calendar cancellation",
                prepare=self.prepare_confirmation_email_in_other_inbox,
                expected=ExpectedResult(response_validators=self.cancel_emailed_booking),
            ),
            RequestScenario(
                name="Uncertain delivery preserves both the booking and the pending sent copy",
                prepare=self.prepare_unconfirmed_email,
                expected=ExpectedResult(response_validators=self.unconfirmed_booking_email),
            ),
            RequestScenario(
                name="An unavailable sender never delivers a booking confirmation",
                prepare=[self.prepare_confirmation_email, self.remove_sender_access],
                expected=ExpectedResult(response_validators=self.unavailable_sender_booking_email),
            ),
            RequestScenario(
                name="Manual approval delivers the booking's meeting link once",
                prepare=[
                    self.use_generated_meetings, self.use_manual_approval, self.prepare_confirmation_email,
                ],
                expected=ExpectedResult(response_validators=self.approved_pending_meeting),
            ),
        ]

    def disable_link(self, scenario: RequestScenario) -> None:
        """Deactivate the offering after the visitor obtained its link."""
        BookingLink.objects.filter(pk=self.booking.pk).update(active=False)

    def set_legacy_hours(self, scenario: RequestScenario) -> None:
        """Store a legacy schedule that the current editor cannot interpret."""
        BookingLink.objects.filter(pk=self.booking.pk).update(
            availability_hours={"legacy_schedule": ["weekdays"]}
        )

    def use_manual_approval(self, scenario: RequestScenario) -> None:
        """Require review of new requests submitted to the booking link."""
        BookingLink.objects.filter(pk=self.booking.pk).update(auto_approve=False)

    def use_generated_meetings(self, scenario: RequestScenario) -> None:
        """Enable conference reservations and store the automatic location choice."""
        self.enterContext(override_settings(BLOOMERP_CONFIG=conferencing_config()))
        BookingLink.objects.filter(pk=self.booking.pk).update(location=CREATE_BOOKING_CONFERENCE)

    def prepare_confirmation_email(
        self, scenario: RequestScenario, *, message: str = "Thanks for booking.\nSee you soon."
    ) -> None:
        """Attach an active sender and substitute a local mock at the transport boundary."""
        self.sender = EmailAccount.objects.create(
            email_address="appointments@example.com", status=EmailAccount.Status.ACTIVE,
        )
        self.email_folder = InboxFolder.objects.create(
            inbox=self.inbox, type="email", related_object_id=str(self.sender.pk),
        )
        self.booking.email_account = self.sender
        self.booking.email_message = message
        self.booking.save(update_fields=["email_account", "email_message"])
        self.email_result = EmailSendResult(
            provider_message_id="booking-confirmation", message_id="<confirmation@example.com>",
        )
        self.email_adapter = Mock()
        self.email_adapter.send_email.return_value = self.email_result
        self.resolve_sender = self.enterContext(patch(
            "bloomerp.communication.builtins.emails.actions._resolve_email_adapter_for_account",
            return_value=self.email_adapter,
        ))

    def prepare_rich_confirmation_email(self, scenario: RequestScenario) -> None:
        """Save editor paragraphs, inline formatting, and markup that must be removed."""
        self.prepare_confirmation_email(
            scenario,
            message=(
                "<p>Thanks for submitting your <strong>availability</strong>.</p>"
                "<p>See you soon &amp; take care.</p>"
                "<script>unsafeEmailScript()</script>"
                '<p><a href="javascript:unsafeEmailLink()">More information</a></p>'
            ),
        )

    def prepare_unconfirmed_email(self, scenario: RequestScenario) -> None:
        """Have the provider return a reference with an uncertain outcome."""
        self.prepare_confirmation_email(scenario)
        self.email_adapter.send_email.side_effect = EmailSendUnconfirmed(self.email_result)

    def prepare_confirmation_email_in_other_inbox(self, scenario: RequestScenario) -> None:
        """Keep the sender accessible through a different inbox from the booking calendar."""
        self.prepare_confirmation_email(scenario)
        self.email_folder.inbox = self.destination
        self.email_folder.save(update_fields=["inbox"])

    def remove_sender_access(self, scenario: RequestScenario) -> None:
        """Move the booking to an organizer without access to the selected account."""
        self.inbox.user = self.normal_user
        self.inbox.save(update_fields=["user"])
        self.email_folder.delete()

    def submit_with_confirmation_callbacks(self) -> HttpResponse:
        """Book through the public route and execute callbacks queued by that request."""
        with TestCase.captureOnCommitCallbacks(execute=True):
            return self.client.post(
                self.booking.get_public_url(),
                {
                    "day": self.day.isoformat(), "slot": self.start.isoformat(),
                    "name": "Guest name", "email": "guest@example.com",
                },
                follow=True,
            )

    def auto_confirmation_email(self, response: HttpResponse) -> bool:
        """Keep safe formatting in HTML and remove markup from the text alternative."""
        self.assertContains(self.submit_with_confirmation_callbacks(), "Booking confirmed")
        self.assert_booking_email(self.booking.location)
        arguments = self.email_adapter.send_email.call_args.kwargs
        self.assertIn(
            "<p>Thanks for submitting your <strong>availability</strong>.</p>",
            arguments["body_html"],
        )
        self.assertIn(
            "Thanks for submitting your availability.\nSee you soon & take care.\nMore information",
            arguments["body_text"],
        )
        for body in (arguments["body_html"], arguments["body_text"]):
            self.assertNotIn("&lt;p&gt;", body)
            self.assertNotIn("unsafeEmailScript", body)
            self.assertNotIn("unsafeEmailLink", body)
        self.assertNotIn("<p>", arguments["body_text"])
        event = self.booking.submissions.get().calendar_event
        self.assertIsNotNone(event.invitation_sent_at)
        self.assertTrue(InboxItem.objects.filter(
            folder=self.email_folder,
            related_item_id=self.email_result.message_id,
            raw_meta_data__calendar_event_id=str(event.pk),
        ).exists())
        return True

    def cancel_emailed_booking(self, response: HttpResponse) -> bool:
        """Send a cancellation revision with the original booking invitation's identity."""
        self.assertContains(self.submit_with_confirmation_callbacks(), "Booking confirmed")
        event = self.booking.submissions.get().calendar_event
        self.email_adapter.send_email.return_value = EmailSendResult(
            provider_message_id="booking-cancellation", message_id="<cancellation@example.com>",
        )
        with patch(
            "bloomerp.communication.calendar.outgoing._resolve_email_adapter_for_account",
            return_value=self.email_adapter,
        ) as resolve_sender:
            cancel_calendar_event(user=self.admin_user, event_id=event.pk)
        resolve_sender.assert_called_once_with(self.sender)
        self.assertEqual(self.email_adapter.send_email.call_count, 2)
        part, = self.email_adapter.send_email.call_args.kwargs["attachments"]
        cancellation = parse_scheduling_message(part.content.decode(), part.calendar_method)
        self.assertEqual(cancellation.method, "CANCEL")
        self.assertEqual(cancellation.uid, event.calendar_uid)
        self.assertEqual(cancellation.sequence, 1)
        event.refresh_from_db()
        return event.cancelled

    def unconfirmed_booking_email(self, response: HttpResponse) -> bool:
        """Keep confirmed bookings and record uncertain sends for reconciliation."""
        self.assertContains(self.submit_with_confirmation_callbacks(), "Booking confirmed")
        self.assert_booking_email(self.booking.location)
        arguments = self.email_adapter.send_email.call_args.kwargs
        self.assertIn("Thanks for booking.\nSee you soon.", arguments["body_text"])
        self.assertIn("<p>Thanks for booking.<br>See you soon.</p>", arguments["body_html"])
        sent = InboxItem.objects.get(
            folder=self.email_folder, related_item_id=self.email_result.message_id,
        )
        event = self.booking.submissions.get().calendar_event
        return sent.raw_meta_data["outbound_send_pending"] is True and event.invitation_sent_at is None

    def unavailable_sender_booking_email(self, response: HttpResponse) -> bool:
        """Keep a confirmed booking when the organizer cannot use the sender."""
        self.assertContains(self.submit_with_confirmation_callbacks(), "Booking confirmed")
        self.resolve_sender.assert_not_called()
        return self.booking.submissions.get().calendar_event.location == self.booking.location

    def assert_booking_email(self, location: str) -> None:
        """Check the message and its iCalendar invitation against the saved event."""
        self.resolve_sender.assert_called_once_with(self.sender)
        self.email_adapter.send_email.assert_called_once()
        self.email_adapter.close.assert_called_once()
        arguments = self.email_adapter.send_email.call_args.kwargs
        self.assertEqual(arguments["to"], ["guest@example.com"])
        self.assertEqual(arguments["subject"], "Booking confirmed: Project consultation")
        start, end = (time_value.astimezone(ZoneInfo(self.booking.timezone)) for time_value in (self.start, self.end))
        self.assertIn(formats.date_format(start, "DATE_FORMAT"), arguments["body_text"])
        self.assertIn(formats.time_format(start, "TIME_FORMAT"), arguments["body_text"])
        self.assertIn(formats.time_format(end, "TIME_FORMAT"), arguments["body_text"])
        self.assertIn(self.booking.timezone, arguments["body_text"])
        self.assertIn(location, arguments["body_text"])
        part, = arguments["attachments"]
        self.assertEqual(part.filename, "invite.ics")
        self.assertEqual(part.content_type, "text/calendar")
        invitation = parse_scheduling_message(part.content.decode(), part.calendar_method)
        event = self.booking.submissions.get().calendar_event
        self.assertEqual(invitation.method, "REQUEST")
        self.assertEqual(invitation.uid, event.calendar_uid)
        self.assertEqual(invitation.organizer, self.sender.email_address)
        self.assertEqual(event.organizer_email, self.sender.email_address)
        self.assertEqual(invitation.attendees, (("guest@example.com", "accepted", "Guest name"),))
        self.assertEqual(invitation.event.decoded("DTSTART"), self.start)
        self.assertEqual(invitation.event.decoded("DTEND"), self.end)
        self.assertEqual(str(invitation.event["LOCATION"]), location)
        self.assertIn("Discuss your project.", str(invitation.event["DESCRIPTION"]))
        self.assertNotIn("<strong>", str(invitation.event["DESCRIPTION"]))

    def add_cancelled_event(self, scenario: RequestScenario) -> None:
        """Place a cancelled meeting at the visitor's selected time."""
        self.block_slot(scenario)
        self.destination.calendar_events.update(cancelled=True)

    def block_slot(self, scenario: RequestScenario) -> None:
        """Make the first slot busy on a destination calendar after selection."""
        event = CalendarEvent.objects.create(
            title="Private event",
            organizer_email="private@example.com",
            start=self.start,
            end=self.end,
            event_timezone=self.booking.timezone,
        )
        event.inboxes.add(self.destination)

    def block_day(self, scenario: RequestScenario) -> None:
        """Place one date-only event on the organizing calendar."""
        CalendarEvent.objects.create(
            title="Private event",
            organizer_email="private@example.com",
            organizing_inbox=self.inbox,
            all_day=True,
            start_date=self.day,
            end_date=self.day + timedelta(days=1),
        )

    def no_submission(self, response: HttpResponse) -> bool:
        """Reject the request without retaining its visitor details."""
        return not self.booking.submissions.exists()

    def approved_event(self, response: HttpResponse) -> bool:
        """Verify the single timed event, inbox placements, and guest identity."""
        submission = self.booking.submissions.get()
        event = submission.calendar_event
        participant = event.participants.get()
        return (
            submission.requested_start is None
            and event.title == self.booking.title
            and event.start == self.start
            and event.end == self.end
            and event.location == self.booking.location
            and event.organizing_inbox_id == self.inbox.pk
            and set(event.inboxes.values_list("pk", flat=True))
            == {self.inbox.pk, self.destination.pk}
            and participant.email == "guest@example.com"
            and participant.display_name == "Guest name"
        )

    def pending_submission(self, response: HttpResponse) -> bool:
        """Retain the visitor and requested duration for later review."""
        submission = self.booking.submissions.get()
        return (
            submission.requested_start == self.start
            and submission.requested_end == self.end
            and submission.email == "guest@example.com"
            and not CalendarEvent.objects.filter(
                calendar_booking_submission=submission
            ).exists()
        )

    def distinct_meeting_locations(self, response: HttpResponse) -> bool:
        """Show each visitor the URL reserved for their specific booking."""
        event = self.booking.submissions.get().calendar_event
        next_booking = self.client.post(
            self.booking.get_public_url(),
            {
                "day": self.day.isoformat(),
                "slot": self.end.isoformat(),
                "name": "Second guest",
                "email": "other@example.com",
            },
            follow=True,
        )
        second_event = self.booking.submissions.get(email="other@example.com").calendar_event
        self.assertContains(response, f'href="{event.location}"')
        self.assertContains(next_booking, f'href="{second_event.location}"')
        self.assertNotContains(next_booking, event.location)
        return (
            event.conference_session_id is not None
            and second_event.conference_session_id is not None
            and event.conference_session_id != second_event.conference_session_id
            and event.conference_session.participants.filter(user=self.admin_user, role="host").exists()
        )

    def approved_pending_meeting(self, response: HttpResponse) -> bool:
        """Send the generated meeting URL only after the first successful approval."""
        response = self.submit_with_confirmation_callbacks()
        self.assertTrue(self.pending_submission(response))
        self.assertNotContains(response, "Open meeting location")
        self.resolve_sender.assert_not_called()
        confirmation_url = response.redirect_chain[-1][0]
        submission = self.booking.submissions.get()
        duplicate = self.client.post(
            self.booking.get_public_url(),
            {
                "day": self.day.isoformat(),
                "slot": self.start.isoformat(),
                "name": "Another visitor",
                "email": submission.email,
            },
        )
        self.assertEqual(duplicate.status_code, 302)
        approval_url = reverse("components_objects_actions", kwargs={
            "content_type_id": ContentType.objects.get_for_model(BookingLinkSubmission).pk,
            "object_id": submission.pk,
            "action_id": "approve_booking",
        })
        PolicyManager.create_policy(
            BookingLinkSubmission,
            global_permissions=["view", "change"],
            field_permissions={"name": ["view"]},
            row_permissions=[RowPolicyRuleContent(permissions=["view", "change"], conditions=[])],
        ).assign_user(self.normal_user)
        self.client.force_login(self.normal_user)
        self.assertEqual(self.client.post(approval_url).status_code, 403)
        self.assertFalse(ConferenceSession.objects.exists())

        self.inbox.user = self.normal_user
        self.inbox.save(update_fields=["user"])
        with TestCase.captureOnCommitCallbacks(execute=True):
            self.assertContains(self.client.post(approval_url), "Booking approved.")
        submission.refresh_from_db()
        event = submission.calendar_event
        with TestCase.captureOnCommitCallbacks(execute=True):
            retried = submission.approve(self.normal_user, meeting_base_url="http://testserver/")
        self.assertEqual(retried.pk, event.pk)
        self.assertEqual(retried.conference_session_id, event.conference_session_id)
        self.assert_booking_email(event.location)
        self.assertIn(f'href="{event.location}"', self.email_adapter.send_email.call_args.kwargs["body_html"])

        self.client.logout()
        confirmed = self.client.get(confirmation_url)
        self.assertContains(confirmed, "Booking confirmed")
        self.assertContains(confirmed, f'href="{event.location}"')
        self.assertNotContains(self.client.get(duplicate.url), event.location)
        return event.conference_session_id is not None and ConferenceSession.objects.count() == 1
